import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-placements',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <h1 style="font-size:24px;font-weight:700;">Placement Drives</h1>
      <button class="btn btn-primary">+ Add Drive</button>
    </div>
    <div class="card"><table><thead><tr><th>Company</th><th>Role</th><th>Package</th><th>Location</th><th>Deadline</th><th>Status</th></tr></thead><tbody>
      <tr *ngFor="let p of drives"><td>{{p.company}}</td><td>{{p.role}}</td><td>{{p.package}}</td><td>{{p.location}}</td><td>{{p.deadline}}</td><td><span class="badge badge-success">Active</span></td></tr>
    </tbody></table></div>
  `
})
export class PlacementsComponent {
  drives = [
    { company: 'Google', role: 'SDE-1', package: '₹25 LPA', location: 'Bangalore', deadline: '30 Jul 2026' },
    { company: 'Amazon', role: 'SDE-1', package: '₹22 LPA', location: 'Hyderabad', deadline: '15 Aug 2026' },
    { company: 'TCS', role: 'Developer', package: '₹7 LPA', location: 'Pune', deadline: '20 Aug 2026' },
  ];
}
